import React, { useState } from 'react';
import { FaMoneyBillWave, FaPlane, FaHotel, FaUtensils, FaShoppingBag, FaTicketAlt } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';
import Modal from './Modal';

const BudgetSelection = ({ isOpen, onClose, onComplete }) => {
  const { theme } = useTheme();
  const [budget, setBudget] = useState({
    total: '',
    accommodation: '',
    food: '',
    activities: '',
    shopping: '',
    transportation: ''
  });

  const handleInputChange = (category, value) => {
    // Only allow numbers and decimal points
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setBudget(prev => ({
        ...prev,
        [category]: value
      }));
    }
  };

  const calculateTotal = () => {
    const values = Object.values(budget).filter(v => v !== '');
    return values.reduce((sum, val) => sum + parseFloat(val), 0).toFixed(2);
  };

  const handleComplete = () => {
    onComplete({
      ...budget,
      total: calculateTotal()
    });
    onClose();
  };

  const budgetCategories = [
    { key: 'accommodation', label: 'Accommodation', icon: FaHotel },
    { key: 'food', label: 'Food & Dining', icon: FaUtensils },
    { key: 'activities', label: 'Activities', icon: FaTicketAlt },
    { key: 'shopping', label: 'Shopping', icon: FaShoppingBag },
    { key: 'transportation', label: 'Transportation', icon: FaPlane }
  ];

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Set Your Budget">
      <div className="space-y-6">
        <div className="flex items-center space-x-4">
          <FaMoneyBillWave style={{ color: theme.primary }} className="text-xl" />
          <h2 className="text-xl font-semibold" style={{ color: theme.text }}>Budget Breakdown</h2>
        </div>

        {/* Total Budget Input */}
        <div className="space-y-2">
          <label className="block text-sm font-medium" style={{ color: theme.text }}>
            Total Budget
          </label>
          <div className="relative">
            <span 
              className="absolute left-3 top-1/2 -translate-y-1/2"
              style={{ color: theme.textLight }}
            >
              $
            </span>
            <input
              type="text"
              value={budget.total}
              onChange={(e) => handleInputChange('total', e.target.value)}
              className="w-full p-2 pl-8 border rounded-lg focus:ring-2 focus:ring-opacity-50 transition-colors"
              style={{ 
                borderColor: theme.border,
                backgroundColor: theme.background,
                color: theme.text,
                '::placeholder': {
                  color: theme.textLight
                }
              }}
              placeholder="Enter total budget"
            />
          </div>
        </div>

        {/* Budget Categories */}
        <div className="space-y-4">
          {budgetCategories.map(({ key, label, icon: Icon }) => (
            <div key={key} className="space-y-2">
              <label className="block text-sm font-medium" style={{ color: theme.text }}>
                {label}
              </label>
              <div className="relative">
                <span 
                  className="absolute left-3 top-1/2 -translate-y-1/2"
                  style={{ color: theme.textLight }}
                >
                  $
                </span>
                <input
                  type="text"
                  value={budget[key]}
                  onChange={(e) => handleInputChange(key, e.target.value)}
                  className="w-full p-2 pl-8 border rounded-lg focus:ring-2 focus:ring-opacity-50 transition-colors"
                  style={{ 
                    borderColor: theme.border,
                    backgroundColor: theme.background,
                    color: theme.text,
                    '::placeholder': {
                      color: theme.textLight
                    }
                  }}
                  placeholder={`Enter ${label.toLowerCase()} budget`}
                />
              </div>
            </div>
          ))}
        </div>

        {/* Total Calculation */}
        {Object.values(budget).some(v => v !== '') && (
          <div 
            className="p-4 rounded-lg"
            style={{ 
              backgroundColor: theme.background,
              border: `1px solid ${theme.border}`
            }}
          >
            <div className="text-sm font-medium" style={{ color: theme.text }}>
              Total Budget
            </div>
            <div className="text-lg font-semibold" style={{ color: theme.primary }}>
              ${calculateTotal()}
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex justify-end space-x-4 mt-8">
          <button
            onClick={onClose}
            className="px-6 py-2 border rounded-lg transition-colors"
            style={{ 
              borderColor: theme.border,
              color: theme.text,
              backgroundColor: theme.background,
              ':hover': {
                backgroundColor: theme.backgroundAlt
              }
            }}
          >
            Cancel
          </button>
          <button
            onClick={handleComplete}
            className="px-6 py-2 rounded-lg transition-colors hover:opacity-90"
            style={{ 
              backgroundColor: theme.primary,
              color: theme.background
            }}
          >
            Confirm
          </button>
        </div>
      </div>
    </Modal>
  );
};

export default BudgetSelection;
